    "Claudex akan menggunakan mouse dan keyboard Anda di {apps}.",
  "the apps you allowed": "aplikasi yang Anda izinkan",
  "Other apps will be hidden until it finishes.":
    "Aplikasi lain akan disembunyikan hingga selesai.",
  "Press Esc to stop at any time.": "Tekan Esc untuk berhenti kapan saja.",
  "Let Claudex see and act in the apps you allow, working in the background or with full control of your screen. Screenshots of those apps are sent to the model.":
    "Izinkan Claudex melihat dan bertindak di aplikasi yang Anda izinkan, bekerja di latar belakang atau dengan kendali penuh atas layar. Tangkapan layar aplikasi tersebut dikirim ke model.",
  "Background: Claudex works inside the apps you allow while you keep using your computer, and asks your permission before taking full control of your screen. Full control: Claudex takes control of your screen, mouse, and keyboard by default whenever Claudex uses an app you allow, without asking again.":
    "Latar belakang: Claudex bekerja di aplikasi yang Anda izinkan saat Anda tetap menggunakan komputer, dan meminta izin sebelum mengambil kendali penuh atas layar. Kendali penuh: setiap kali Claudex menggunakan aplikasi yang Anda izinkan, Claudex secara default mengendalikan layar, mouse, dan keyboard tanpa bertanya lagi.",
  "Claudex uses your computer's OpenSSH. Passwords are never saved; use an SSH key and ssh-agent to connect without prompts.":
    "Claudex menggunakan OpenSSH komputer Anda. Kata sandi tidak pernah disimpan; gunakan kunci SSH dan ssh-agent untuk terhubung tanpa permintaan interaktif.",
  "Run Code sessions on another computer over SSH. Claudex uses this computer's OpenSSH and your SSH keys; passwords are never saved.":
    "Jalankan sesi Code di komputer lain melalui SSH. Claudex menggunakan OpenSSH komputer ini dan kunci SSH Anda; kata sandi tidak pernah disimpan.",
  ".md file must contain skill name and description formatted in YAML":
    "File .md harus berisi nama dan deskripsi skill dalam format YAML",
  ".zip or .skill file must include a SKILL.md file":
    "File .zip atau .skill harus menyertakan file SKILL.md",
  "Claudex references the same knowledge every time you talk to it in this project.":
    "Claudex merujuk pengetahuan yang sama setiap kali Anda berbicara dengannya dalam proyek ini.",
  "Provide Claudex with relevant instructions and information for chats within {name}. This will work alongside your personal instructions and the selected style in a chat.":
    "Berikan instruksi dan informasi yang relevan kepada Claudex untuk chat di {name}. Ini akan digunakan bersama instruksi pribadi dan gaya yang dipilih dalam chat.",
