  "Scan with {method} to pay {amount}":
    "Pindai dengan {method} untuk membayar {amount}",
  "Pay {amount} there. Your plan and balance update when the payment goes through.":
    "Bayar {amount} di sana. Paket dan saldo Anda diperbarui setelah pembayaran berhasil.",
  "The payment page for {amount} opened in your browser. This window updates when the payment goes through.":
    "Halaman pembayaran sebesar {amount} dibuka di browser Anda. Jendela ini diperbarui setelah pembayaran berhasil.",
  "Amount ({currency})": "Jumlah ({currency})",
  "Fee ({percent}%)": "Biaya ({percent}%)",
  "QR code to pay {amount} with {method}":
    "Kode QR untuk membayar {amount} dengan {method}",
  "{count} hook that runs commands": "{count} hook yang menjalankan perintah",
  "{count} hooks that run commands": "{count} hook yang menjalankan perintah",
  "Added. It also uses {services}, which need signing in before Claudex can use them.":
    "Ditambahkan. Ini juga menggunakan {services}, yang memerlukan proses masuk sebelum Claudex dapat menggunakannya.",
  "Make sure you trust a plugin before installing, updating, or using it. Plugins installed from marketplaces are not controlled by Anthropic, and Anthropic cannot verify that they will work as intended or that they won't change. See each plugin's homepage for more information.":
    "Pastikan Anda memercayai plugin sebelum menginstal, memperbarui, atau menggunakannya. Plugin yang diinstal dari marketplace tidak dikendalikan oleh Anthropic, dan Anthropic tidak dapat memastikan bahwa plugin akan bekerja sesuai harapan atau tidak berubah. Lihat halaman utama setiap plugin untuk informasi lebih lanjut.",
  "Updated tasks · {done} of {total} done":
    "Tugas diperbarui · {done} dari {total} selesai",
  "Bypass all permission checks and let Claudex work uninterrupted in folders you confirm. This works well for workflows like fixing lint errors or generating boilerplate code. Letting Claudex run arbitrary commands is risky and can result in data loss, system corruption, or data exfiltration (e.g., via prompt injection attacks).":
    "Lewati semua pemeriksaan izin dan biarkan Claudex bekerja tanpa gangguan di folder yang Anda konfirmasi. Ini cocok untuk alur kerja seperti memperbaiki kesalahan lint atau membuat kode boilerplate. Mengizinkan Claudex menjalankan perintah apa pun berisiko dan dapat menyebabkan kehilangan data, kerusakan sistem, atau kebocoran data, misalnya melalui serangan injeksi prompt.",
  "How Claudex structures its responses in Code sessions. Applies to new sessions; the session menu can override it for a single session.":
    "Cara Claudex menyusun respons dalam sesi Code. Berlaku untuk sesi baru; menu sesi dapat menggantinya untuk satu sesi.",
