  "Xcode is installed, but your Mac’s command-line tools don’t point at it. In Xcode, open Settings → Locations and pick your Xcode under Command Line Tools.":
    "Xcode sudah terpasang, tetapi command-line tools di Mac Anda tidak mengarah ke sana. Di Xcode, buka Settings → Locations dan pilih Xcode Anda di bagian Command Line Tools.",
  "Xcode is installed, but your Mac’s command-line tools don’t point at it. Paste this in Terminal, then press Enter and type your Mac password when it asks:":
    "Xcode sudah terpasang, tapi command-line tools di Mac Anda belum mengarah ke sana. Tempel ini di Terminal, lalu tekan Enter dan ketik kata sandi Mac Anda saat diminta:",
