    "PR siap di-merge sekarang — tidak ada yang perlu ditunggu.",
  "This repository doesn’t allow auto-merge. An admin can turn on Allow auto-merge in the repository settings on GitHub.":
    "Repositori ini tidak mengizinkan merge otomatis. Admin dapat mengaktifkan Allow auto-merge di pengaturan repositori di GitHub.",
  "This pull request is ready to merge now, so there’s nothing for auto-merge to wait for.":
    "Pull request ini siap di-merge sekarang, jadi tidak ada yang perlu ditunggu oleh merge otomatis.",
  "This repository doesn’t allow squash merging, which auto-merge uses here. Turn on auto-merge on GitHub to pick an allowed merge method.":
    "Repositori ini tidak mengizinkan squash merge, yang digunakan merge otomatis di sini. Aktifkan merge otomatis di GitHub untuk memilih metode merge yang diizinkan.",
  "GitHub only offers auto-merge on protected base branches, and this one isn’t protected. An admin can add a branch protection rule on GitHub.":
    "GitHub hanya menawarkan merge otomatis pada branch dasar yang dilindungi, dan branch ini tidak dilindungi. Admin dapat menambahkan aturan perlindungan branch di GitHub.",
  "GitHub doesn’t support auto-merge on stacked pull requests.":
    "GitHub tidak mendukung merge otomatis pada pull request bertumpuk.",
  "Your GitHub account doesn’t have permission to change auto-merge on this repository. Ask a repository admin for access.":
    "Akun GitHub Anda tidak memiliki izin untuk mengubah merge otomatis di repositori ini. Minta akses ke admin repositori.",
  "This pull request changes a workflow file, and your GitHub CLI sign-in lacks the workflow scope. Run gh auth refresh -s workflow to add it.":
    "Pull request ini mengubah file workflow, dan login GitHub CLI Anda tidak memiliki cakupan workflow. Jalankan gh auth refresh -s workflow untuk menambahkannya.",
