  "Prep a stakeholder update": "Siapkan pembaruan untuk pemangku kepentingan",
  "Help me prep a stakeholder update — what to lead with and what questions to expect.":
    "Bantu saya menyiapkan pembaruan untuk pemangku kepentingan — apa yang harus disampaikan lebih dulu dan pertanyaan apa yang mungkin muncul.",
  "Prioritize my backlog": "Prioritaskan backlog saya",
  "Give me a framework for prioritizing backlog items by impact and effort, and show me how to spot the easy wins. I’ll paste my items next.":
    "Beri saya kerangka untuk memprioritaskan item backlog berdasarkan dampak dan upaya, dan tunjukkan cara menemukan kemenangan cepat. Saya akan menempelkan item saya berikutnya.",
  "Debug unexpected behavior": "Debug perilaku yang tidak terduga",
  "I’m seeing unexpected behavior or errors in a system. Help me work through it systematically — I’ll share details on what’s happening.":
    "Saya melihat perilaku tak terduga atau error di sebuah sistem. Bantu saya menelusurinya secara sistematis — saya akan membagikan detail apa yang terjadi.",
  "Evaluate architecture tradeoffs": "Evaluasi pertimbangan arsitektur",
  "Help me compare engineering design options. I’ll describe two approaches; weigh the tradeoffs and tell me which you’d pick and why.":
    "Bantu saya membandingkan opsi desain teknik. Saya akan menjelaskan dua pendekatan; timbang untung ruginya dan beri tahu mana yang akan Anda pilih dan alasannya.",
  "Plan an eng project": "Rencanakan proyek engineering",
  "Help me scope an engineering project: phases, dependencies, and risks.":
    "Bantu saya menentukan cakupan proyek engineering: fase, dependensi, dan risiko.",
  "Draft a job description": "Susun deskripsi pekerjaan",
