  "Discard your annotations?": "Buang anotasi Anda?",
  "You have unsaved marks on this image. Discarding removes them.":
    "Anda memiliki tanda yang belum disimpan pada gambar ini. Membuangnya akan menghapusnya.",
  Annotate: "Anotasi",
  "Annotate image": "Beri anotasi pada gambar",
