  "Nothing to undo yet": "Belum ada yang bisa diurungkan",
  "Nothing to redo yet": "Belum ada yang bisa diulang",
  "Nothing to clear yet": "Belum ada yang bisa dihapus",
  "Couldn’t save your annotations. Try again.":
    "Anotasi Anda tidak dapat disimpan. Coba lagi.",
  "Couldn’t capture a screenshot to annotate. Try again.":
    "Tidak dapat mengambil screenshot untuk diberi anotasi. Coba lagi.",
  "The annotated screenshot is too large to add to the chat. Try a smaller display or scale.":
    "Screenshot yang diberi anotasi terlalu besar untuk ditambahkan ke chat. Coba tampilan atau skala yang lebih kecil.",
  "Sketch canvas": "Kanvas sketsa",
  "Text label": "Label teks",
  "Get embed code": "Dapatkan kode sematan",
  "Back to publish settings": "Kembali ke pengaturan publikasi",
  "Allowed domains": "Domain yang diizinkan",
  "Only these domains can embed this artifact. Separate with commas.":
    "Hanya domain ini yang dapat menyematkan artefak ini. Pisahkan dengan koma.",
  "{invalidDomain} is not a valid domain":
    "{invalidDomain} bukan domain yang valid",
  "{invalidDomains} are not valid domains":
    "{invalidDomains} bukan domain yang valid",
  "Embed code": "Kode sematan",
  "Copy code": "Salin kode",
  "Copy this prompt into a chat with your other AI provider":
    "Salin prompt ini ke obrolan dengan penyedia AI Anda yang lain",
  "Copy prompt": "Salin prompt",
  "Paste the results below to add them to Claudex’s memory":
    "Tempel hasilnya di bawah untuk menambahkannya ke memori Claudex",
  "Paste your memory details here": "Tempel detail memori Anda di sini",
