  "Automatically archive desktop sessions when the associated pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept.":
    "Arsipkan sesi desktop secara otomatis saat pull request terkait digabungkan atau ditutup. Setelah pull request digabungkan, pengarsipan juga menghapus worktree sesi dan branch-nya. Pekerjaan yang belum di-push tetap disimpan.",
  "Archive this session when its pull request is merged or closed. Archiving also removes the session’s worktree and deletes its branch once the pull request is merged. Work that isn’t pushed is kept. This session only; other sessions follow the default in Settings → Claudex Code.":
    "Arsipkan sesi ini saat pull request-nya digabungkan atau ditutup. Setelah pull request digabungkan, pengarsipan juga menghapus worktree sesi dan branch-nya. Pekerjaan yang belum di-push tetap disimpan. Hanya sesi ini; sesi lain mengikuti default di Pengaturan → Claudex Code.",
  "Git won’t check out a branch in two folders at once. Run git worktree list in the repository to see which folder has this branch, switch that folder to a different branch, then try again.":
    "Git tidak mengizinkan satu branch di-checkout di dua folder sekaligus. Jalankan git worktree list di repositori untuk melihat folder mana yang memakai branch ini, alihkan folder itu ke branch lain, lalu coba lagi.",
