    "Ketuk “Tambahkan ke layar utama”, lalu ikuti petunjuk di layar.",
  "In Safari’s menu bar, choose File, then Add to Dock. This needs macOS Sonoma or later.":
    "Di bar menu Safari, pilih File, lalu Tambahkan ke Dock. Fitur ini memerlukan macOS Sonoma atau versi yang lebih baru.",
  "Click Add.": "Klik Tambahkan.",
  "Open it from your Dock. You may need to sign in again the first time.":
    "Buka artefak dari Dock Anda. Anda mungkin perlu masuk lagi saat pertama kali membukanya.",
  "Checking whether this browser can install this artifact":
    "Memeriksa apakah browser ini dapat menginstal artefak ini",
  "Tools to allow": "Alat yang akan diizinkan",
  "From {connector}": "Dari {connector}",
  "These tools are from {connector}. Claudex may decide when this artifact runs them. After you allow them, this artifact can run them without asking.":
    "Alat-alat ini berasal dari {connector}. Claudex dapat menentukan kapan artefak ini menjalankannya. Setelah Anda mengizinkannya, artefak ini dapat menjalankannya tanpa meminta persetujuan.",
  "Claudex may decide when this artifact runs these tools. After you allow them, this artifact can run them without asking.":
    "Claudex dapat menentukan kapan artefak ini menjalankan alat tersebut. Setelah Anda mengizinkannya, artefak ini dapat menjalankan alat tersebut tanpa meminta izin.",
  "This time it will run {tool} and send":
    "Kali ini artefak akan menjalankan {tool} dan mengirim",
  "It will send": "Data yang akan dikirim",
  "Nothing — this call has no arguments.":
    "Tidak ada — panggilan ini tidak memiliki argumen.",
  "This call’s arguments are too long to review here, so it can’t be allowed.":
    "Argumen panggilan ini terlalu panjang untuk ditinjau di sini, jadi tidak dapat diizinkan.",
  "{address} is invited.": "{address} telah diundang.",
  "Claudex artifact": "Artefak Claudex",
  "Let this artifact run these 1 tool?":
    "Izinkan artefak ini menjalankan 1 alat ini?",
