  Standard: "Standar",
  "Your next response will be slower and use more tokens. This task is cached for the current model. Switching to <bold>{targetLabel}</bold> means the full history gets re-read on your next message.":
    "Respons berikutnya akan lebih lambat dan menggunakan lebih banyak token. Tugas ini di-cache untuk model saat ini. Beralih ke <bold>{targetLabel}</bold> berarti seluruh riwayat dibaca ulang pada pesan Anda berikutnya.",
  "Your next response will be slower and use more tokens. This task is cached for the current effort level. Switching to <bold>{targetLabel}</bold> means the full history gets re-read on your next message.":
    "Respons berikutnya akan lebih lambat dan menggunakan lebih banyak token. Tugas ini di-cache untuk tingkat upaya saat ini. Beralih ke <bold>{targetLabel}</bold> berarti seluruh riwayat dibaca ulang pada pesan Anda berikutnya.",
  "Your next response will be slower and use more tokens. This task is cached for the current thinking mode. Switching to <bold>{targetLabel}</bold> means the full history gets re-read on your next message.":
    "Respons berikutnya akan lebih lambat dan menggunakan lebih banyak token. Tugas ini di-cache untuk mode berpikir saat ini. Beralih ke <bold>{targetLabel}</bold> berarti seluruh riwayat dibaca ulang pada pesan Anda berikutnya.",
