  "This is an example project. Create a new project to work with your own documents.":
    "Ini adalah proyek contoh. Buat proyek baru untuk bekerja dengan dokumen Anda sendiri.",
  "A project for studying your course materials, where Claudex helps visualize key concepts, build comprehensive study guides, and tutor you according to your learning needs.":
    "Proyek untuk mempelajari materi kuliah, tempat Claudex membantu memvisualisasikan konsep utama, membuat panduan belajar lengkap, dan membimbing sesuai kebutuhan belajar Anda.",
  "A project for exploring career opportunities, where Claudex helps match your skills to potential careers, improve your resume, and develop personalized roadmaps for professional growth.":
    "Proyek untuk menjelajahi peluang karier, tempat Claudex membantu mencocokkan keterampilan dengan karier potensial, memperbaiki resume, dan membuat peta jalan pertumbuhan profesional pribadi.",
  "A project for developing academic research, where Claudex helps identify key themes in your research, create structured outlines, and provide feedback to improve your drafts.":
    "Proyek untuk mengembangkan penelitian akademik, tempat Claudex membantu mengidentifikasi tema utama, membuat kerangka terstruktur, dan memberikan masukan untuk memperbaiki draf.",
