    "Tidak dapat menautkan tugas ini ke komputer ini.",
  "Computer access is off, so tasks that require a computer won’t run.":
    "Akses komputer nonaktif, jadi tugas yang memerlukannya tidak akan berjalan.",
  "This task will run on schedule once Computer access is on.":
    "Tugas ini akan berjalan sesuai jadwal setelah akses komputer diaktifkan.",
  "Permission mode is set to Auto.": "Mode izin diatur ke Otomatis.",
  "Skip all approvals is on.": "Lewati semua persetujuan aktif.",
  "Claudex runs on its own and pauses if anything looks unsafe. This includes using your connectors and apps on your computer, unless you turn them off.":
    "Claudex berjalan sendiri dan berhenti sementara jika ada yang tampak tidak aman. Ini termasuk penggunaan konektor dan aplikasi di komputer Anda, kecuali jika dinonaktifkan.",
  "Claudex never pauses, even for unsafe actions. This includes using your connectors and apps on your computer. You can turn off individual connectors in the + menu.":
    "Claudex tidak pernah berhenti sementara, bahkan untuk tindakan yang tidak aman. Ini termasuk penggunaan konektor dan aplikasi di komputer Anda. Anda dapat menonaktifkan konektor satu per satu di menu +.",
  "Claudex will work, browse the web, and use any connectors you’ve enabled without pausing for approval. This can put your data at risk.":
    "Claudex akan bekerja, menjelajahi web, dan menggunakan konektor yang diaktifkan tanpa berhenti untuk meminta persetujuan. Ini dapat membahayakan data Anda.",
  "See safe use tips": "Lihat tips penggunaan aman",
  "1 tool": "1 alat",
  "{count} tools": "{count} alat",
  "Will link after this step": "Akan ditautkan setelah langkah ini",
  "This task is in the middle of a step and will switch to this computer when the step finishes.":
    "Tugas ini sedang menjalankan langkah dan akan beralih ke komputer ini setelah selesai.",
  "This task is in the middle of a step. Wait for it to finish (or stop it), then link again.":
    "Tugas ini sedang menjalankan langkah. Tunggu hingga selesai atau hentikan, lalu tautkan lagi.",
  "This kind of task can’t be linked to a computer.":
    "Jenis tugas ini tidak dapat ditautkan ke komputer.",
  "A scheduled task uses this task, so it can’t be linked to a computer.":
    "Tugas terjadwal menggunakan tugas ini, sehingga tidak dapat ditautkan ke komputer.",
  "This task already has a repository, so it can’t be linked to a computer. To use this computer’s files and apps, start a new task here, then ask Claudex to add the repository.":
    "Tugas ini sudah memiliki repositori, sehingga tidak dapat ditautkan ke komputer. Untuk menggunakan file dan aplikasi komputer ini, mulai tugas baru di sini, lalu minta Claudex menambahkan repositori.",
  "This task is too long to link to a computer. To use this computer’s files and apps, start a new task here.":
    "Tugas ini terlalu panjang untuk ditautkan ke komputer. Mulai tugas baru di sini untuk menggunakan file dan aplikasi komputer ini.",
  "Something earlier in this task can’t be carried over to a computer. To use this computer’s files and apps, start a new task here.":
    "Sebagian isi sebelumnya dari tugas ini tidak dapat dipindahkan ke komputer. Mulai tugas baru di sini untuk menggunakan file dan aplikasi komputer ini.",
  "This task was just linked to a different computer, so it wasn’t changed.":
    "Tugas ini baru saja ditautkan ke komputer lain, sehingga tidak diubah.",
  "Sign in to Claudex again on this computer, then link this task.":
    "Masuk kembali ke Claudex di komputer ini, lalu tautkan tugas ini.",
