  "Claudex is working on your computer. You’ll see updates here as Claudex makes progress.":
    "Claudex sedang bekerja di komputer Anda. Anda akan melihat pembaruan di sini seiring kemajuan Claudex.",
  "Chats compact less since tools aren’t pre-loaded.":
    "Chat lebih jarang dipadatkan karena alat tidak dimuat sebelumnya.",
