    "Lampiran file dihapus karena draf direset setelah percakapan suara yang belum selesai. Lampirkan lagi.",
  "Deleting your account is permanent. You will have no way of recovering your account or conversation data.":
    "Penghapusan akun bersifat permanen. Anda tidak akan dapat memulihkan akun atau data percakapan Anda.",
