  "Block nonessential services": "Blokir layanan nonesensial",
  "Connector favicons, artifact-preview and MCP Apps iframes, and the Linux spellcheck dictionary. Connector widgets fall back to text; spellcheck is off on Linux.":
    "Favicon konektor, iframe pratinjau artefak dan MCP Apps, serta kamus pemeriksa ejaan Linux. Widget konektor beralih ke teks; pemeriksaan ejaan nonaktif di Linux.",
  "This disables connector icons, hosted artifact previews and MCP Apps widgets, and also turns spellcheck off on Linux. Artifacts still render locally. Connectors that return MCP Apps show the text tool result instead of the widget.":
    "Ini menonaktifkan ikon konektor, pratinjau artefak yang dihosting, dan widget MCP Apps, serta pemeriksaan ejaan di Linux. Artefak tetap dirender secara lokal. Konektor yang mengembalikan MCP Apps menampilkan hasil alat berupa teks, bukan widget.",
  "Allow Claudex to use coarse location metadata (city/region) to improve product experiences. <a>Learn more</a>.":
    "Izinkan Claudex menggunakan metadata lokasi perkiraan (kota/wilayah) untuk meningkatkan pengalaman produk. <a>Pelajari lebih lanjut</a>.",
