    "Anda menambahkan konektor ini. Anthropic belum meninjaunya.",
  "This extension was uploaded by your organization.":
    "Ekstensi ini diunggah oleh organisasi Anda.",
  "Community connectors have undergone automated reviews but aren’t verified by Anthropic. We don’t control the tools they make available and can’t guarantee they’ll work as intended or won’t change, so only connect developers you trust.":
    "Konektor komunitas telah melalui peninjauan otomatis, tetapi tidak terverifikasi oleh Anthropic. Kami tidak mengontrol alat yang mereka sediakan dan tidak dapat menjamin alat tersebut berfungsi sesuai harapan atau tidak berubah, jadi hubungkan hanya konektor dari pengembang yang Anda percayai.",
  "Community desktop extensions aren’t verified by Anthropic. We don’t control the tools they make available and can’t guarantee they’ll work as intended or won’t change, so only install desktop extensions from developers you trust.":
    "Ekstensi desktop komunitas tidak terverifikasi oleh Anthropic. Kami tidak mengontrol alat yang mereka sediakan dan tidak dapat menjamin alat tersebut berfungsi sesuai harapan atau tidak berubah, jadi instal hanya ekstensi desktop dari pengembang yang Anda percayai.",
  "Community plugins aren’t verified by Anthropic. We don’t control the tools they make available and can’t guarantee they’ll work as intended or won’t change, so only add plugins from developers you trust.":
    "Plugin komunitas tidak terverifikasi oleh Anthropic. Kami tidak mengontrol alat yang mereka sediakan dan tidak dapat menjamin alat tersebut berfungsi sesuai harapan atau tidak berubah, jadi tambahkan hanya plugin dari pengembang yang Anda percayai.",
  "Connectors let Claudex work with your team’s tools and data. Add them from the directory, or add a custom one.":
    "Konektor memungkinkan Claudex bekerja dengan alat dan data tim Anda. Tambahkan dari direktori, atau tambahkan konektor kustom.",
  "Connectors let Claudex work with your team’s tools and data. Add them from the directory.":
    "Konektor memungkinkan Claudex bekerja dengan alat dan data tim Anda. Tambahkan dari direktori.",
  "Kept on the server, sent only to this connector and never shown again. Servers that sign in with OAuth don’t need one: use Connect after adding.":
    "Disimpan di server, dikirim hanya ke konektor ini, dan tidak ditampilkan lagi. Server yang login dengan OAuth tidak memerlukannya: gunakan Hubungkan setelah menambahkan.",
  "Incorrect code entered. Check that the code matches what you received in your other browser or device and try again.":
    "Kode yang dimasukkan salah. Pastikan kode cocok dengan yang Anda terima di browser atau perangkat lain, lalu coba lagi.",
