  "Alternation (|) isn't allowed — use the Multiple URLs option instead":
    "Alternasi (|) tidak diizinkan — gunakan opsi Beberapa URL",
  "Avoid nested repetition like (a+)+ — it can hang on long inputs":
    "Hindari pengulangan bertingkat seperti (a+)+ — ini bisa macet pada input panjang",
  "Doesn't match the allowed URLs": "Tidak cocok dengan URL yang diizinkan",
  "Doesn't match the allowed characters":
    "Tidak cocok dengan karakter yang diizinkan",
  "Lookarounds and backreferences aren't supported — rewrite without (?=, (?!, (?<=, (?<! or \\1-style references":
    "Lookaround dan referensi balik tidak didukung — tulis ulang tanpa (?=, (?!, (?<=, (?<! atau referensi bergaya \\1",
  "Mark the part each customer fills in, like ${user_config.mydomain}":
    "Tandai bagian yang diisi setiap pelanggan, seperti ${user_config.mydomain}",
  "Must be 400 characters or fewer": "Harus maksimal 400 karakter",
  "Not a valid regular expression": "Bukan ekspresi reguler yang valid",
  "Only the subdomain may vary — end the host with your literal domain, e.g. ^https://[a-z0-9-]+\\.mcp\\.example\\.com/mcp$":
    "Hanya subdomain yang boleh bervariasi — akhiri host dengan domain literal Anda, misalnya ^https://[a-z0-9-]+\\.mcp\\.example\\.com/mcp$",
  "Pattern must end with $ so it can't match a longer host":
    "Pola harus diakhiri dengan $ agar tidak cocok dengan host yang lebih panjang",
  "Pattern must start with ^https://": "Pola harus diawali dengan ^https://",
  "Remove the @ — userinfo before the host isn't allowed":
    "Hapus @ — informasi pengguna sebelum host tidak diizinkan",
  "Server URL must start with https://":
    "URL server harus diawali dengan https://",
  "The subdomain slot can't use wildcards that match `/`, `.`, `?`, `#` or `@` — use a character class like [a-z0-9-]+ instead of .+ or \\S+":
    "Bagian subdomain tidak boleh memakai wildcard yang cocok dengan `/`, `.`, `?`, `#` atau `@` — gunakan kelas karakter seperti [a-z0-9-]+ alih-alih .+ atau \\S+",
  "This field is required": "Kolom ini wajib diisi",
  "Use one ${user_config.key} only": "Gunakan hanya satu ${user_config.key}",
  "Edit connector": "Edit konektor",
  "Delete and re-add connectors to edit custom OAuth Client IDs.":
    "Hapus lalu tambahkan kembali konektor untuk mengedit ID klien OAuth khusus.",
  "Delete and re-add connectors to edit custom OAuth Client Secrets.":
    "Hapus lalu tambahkan kembali konektor untuk mengedit rahasia klien OAuth khusus.",
  "Claudex can’t reach a local address like this one. Enter a public https:// URL.":
    "Claudex tidak dapat menjangkau alamat lokal seperti ini. Masukkan URL https:// publik.",
  "Turn on computer use?": "Aktifkan penggunaan komputer?",
  "Grant macOS permissions": "Berikan izin macOS",
  "Keep in mind:": "Perlu diingat:",
  "Some actions can’t be undone.": "Beberapa tindakan tidak dapat dibatalkan.",
  "Apps you approve could open other apps that you haven’t approved.":
    "Aplikasi yang Anda setujui dapat membuka aplikasi lain yang belum Anda setujui.",
  "Websites and docs could contain malicious instructions that misdirect Claudex.":
    "Situs web dan dokumen dapat berisi instruksi berbahaya yang menyesatkan Claudex.",
  "Close anything sensitive. Claudex can see your screen.":
    "Tutup apa pun yang sensitif. Claudex dapat melihat layar Anda.",
  "Close anything sensitive. Claudex can see what’s on screen in the apps you approve, and your whole screen when Claudex has full control.":
    "Tutup apa pun yang sensitif. Claudex dapat melihat isi layar di aplikasi yang Anda setujui, dan seluruh layar saat memegang kendali penuh.",
  "This is a research preview. Start with tasks where mistakes are easy to fix.":
    "Ini adalah pratinjau riset. Mulailah dengan tugas yang kesalahannya mudah diperbaiki.",
  "Read safe use tips": "Baca tips penggunaan aman",
  "Computer use is on. To finish setup, grant the macOS permissions below.":
    "Penggunaan komputer aktif. Untuk menyelesaikan penyiapan, berikan izin macOS di bawah.",
  Denied: "Ditolak",
  "Not requested": "Belum diminta",
  "Background computer use": "Penggunaan komputer di latar belakang",
  "Claudex will see your whole screen and use your mouse and keyboard on it. You’ll approve the apps Claudex asks for, but on this system access can’t be limited to them, and you won’t confirm each step Claudex performs.":
    "Claudex akan melihat seluruh layar dan menggunakan mouse serta keyboard Anda. Anda menyetujui aplikasi yang diminta, tetapi di sistem ini akses tidak dapat dibatasi ke aplikasi tersebut, dan Anda tidak mengonfirmasi setiap langkah.",
  "Claudex will see the apps you approve and click and type in them, working in the background while you keep using your computer or taking full control of your screen. Which of those Claudex does by default is set under Settings → This computer → Computer use. You’ll approve each app, but not confirm each step Claudex performs.":
    "Claudex akan melihat aplikasi yang Anda setujui serta mengklik dan mengetik di dalamnya, di latar belakang saat Anda tetap memakai komputer atau dengan kendali penuh atas layar. Perilaku bawaan diatur di Pengaturan → Komputer ini → Penggunaan komputer. Anda menyetujui setiap aplikasi, tetapi tidak mengonfirmasi setiap langkah.",
  "Claudex can now control your applications in the background without taking over your screen, and will ask your permission if Claudex needs full control of your mouse and keyboard. If you’d prefer Claudex to default to full control instead of background mode, you can change this at any time under Settings → This computer → Computer use.":
    "Claudex kini dapat mengendalikan aplikasi Anda di latar belakang tanpa mengambil alih layar, dan akan meminta izin jika memerlukan kendali penuh atas mouse dan keyboard. Jika Anda lebih suka kendali penuh sebagai bawaan, Anda dapat mengubahnya kapan saja di Pengaturan → Komputer ini → Penggunaan komputer.",
