    "Hanya gunakan konektor dari pengembang yang Anda percayai. Claudex tidak mengendalikan alat yang disediakan pengembang dan tidak dapat memverifikasi bahwa alat tersebut akan berfungsi sesuai tujuan atau tidak akan berubah.",
