  "For this reflection to work, you’ll need to enable memory in <a>memory settings</a>.":
    "Agar refleksi ini berfungsi, Anda perlu mengaktifkan memori di <a>pengaturan memori</a>.",
  "Search by name": "Cari berdasarkan nama",
  "Build connectors and plugins": "Membuat konektor dan plugin",
  "A connector is an MCP server: it speaks the Model Context Protocol over streamable HTTP, signs people in with OAuth or a token, and describes each tool’s inputs and effects plainly. A plugin bundles skills, connectors and instructions into one package. Add your connector as a custom connector under Customize → Connectors and try it in a chat before you send it with Submit to the directory.":
    "Konektor adalah server MCP: ia menggunakan Model Context Protocol melalui streamable HTTP, memasukkan orang dengan OAuth atau token, dan menjelaskan masukan serta efek setiap alat dengan jelas. Plugin menggabungkan skill, konektor, dan instruksi dalam satu paket. Tambahkan konektor Anda sebagai konektor kustom di Kustomisasi → Konektor dan coba dalam chat sebelum mengirimnya dengan Kirim ke direktori.",
